from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class AldSelectionModeInfo(SchemaObject):
    act_ald_sharing = SchemaField(name='actAldSharing', not_null=True)
    ald_selection_mode = SchemaField(name='aldSelectionMode')
    ald_scanning_interval = SchemaField(name='aldScanningInterval')

    def __init__(self, act_ald_sharing, ald_selection_mode, ald_scanning_interval):
        self.act_ald_sharing = act_ald_sharing
        self.ald_selection_mode = ald_selection_mode
        self.ald_scanning_interval = ald_scanning_interval

        super(AldSelectionModeInfo, self).__init__()
